<template><transition name="sf-modal"><div v-if="open" class="sf-modal-overlay" :class="{'sf-modal-overlay--contained':contained,'sf-modal-overlay--dialog':presentation==='dialog'}" @click.self="requestClose('backdrop')"><section ref="panel" class="sf-modal" :class="[contentClass,'sf-modal--'+presentation]" :role="alert?'alertdialog':'dialog'" :aria-label="title?null:label" :aria-labelledby="title?id+'-title':null" aria-modal="true" tabindex="-1" :style="panelStyle">
  <button v-if="resizable&&presentation==='sheet'" type="button" class="sf-sheet-grabber" aria-label="Resize sheet" :disabled="busy" @click="toggleDetent" @keydown="resizeKey" @pointerdown="dragStart" @pointermove="dragMove" @pointerup="dragEnd" @pointercancel="dragCancel"><span></span></button><div v-else-if="presentation==='sheet'" class="sf-sheet-static-handle" aria-hidden="true"></div>
  <header class="sf-modal__header"><h2 v-if="title" :id="id+'-title'">{{ title }}</h2><span v-else></span><button type="button" class="sf-icon-button sheet-close" :disabled="busy" aria-label="Close" @click="requestClose('button')"><sf-icon name="close" :size="20"/></button></header><div class="sf-modal__body"><slot/></div><footer v-if="$slots.footer" class="sf-modal__footer"><slot name="footer"/></footer>
</section></div></transition></template>
<script>
import SfIcon from './SfIcon'
import {acquireModal,isTopModal,releaseModal,restoreModalFocus,focusableElements} from '../modal-state'
let sequence=0
export default {name:'SfModal',components:{SfIcon},model:{prop:'open',event:'input'},props:{open:Boolean,title:String,label:{type:String,default:'Action confirmation'},presentation:{type:String,default:'sheet'},contained:Boolean,busy:Boolean,dismissible:{type:Boolean,default:true},resizable:{type:Boolean,default:true},detent:{type:String,default:'auto'},contentClass:String,initialFocus:String,alert:Boolean},data(){return {id:'sf-modal-'+(++sequence),activeDetent:this.detent,dragY:0,dragOrigin:null,suppressHandleClick:false}},computed:{panelStyle(){return {'--sf-sheet-height':this.activeDetent==='large'?'86%':this.activeDetent==='medium'?'52%':'auto',transform:this.dragY?'translateY('+this.dragY+'px)':null}}},watch:{open(value){if(value){this.activeDetent=this.detent;this.$nextTick(this.activate)}else{this.dragCancel();this.deactivate()}},busy(value){if(value)this.dragCancel()}},mounted(){if(this.open)this.activate()},beforeDestroy(){this.deactivate()},methods:{
  activate(){if(!this.open||!this.$refs.panel||this.modalSession)return;this.modalSession=acquireModal(this.$el,this.contained);document.addEventListener('keydown',this.onKey,true);document.addEventListener('focusin',this.keepFocus,true);this.focusInitial();this.$emit('opened')},
  deactivate(){const session=this.modalSession;if(!session)return;this.modalSession=null;document.removeEventListener('keydown',this.onKey,true);document.removeEventListener('focusin',this.keepFocus,true);releaseModal(session);this.$nextTick(()=>restoreModalFocus(session))},
  focusInitial(){const panel=this.$refs.panel;if(!panel)return;const target=this.initialFocus&&panel.querySelector(this.initialFocus);(target&&!target.disabled?target:focusableElements(panel).find(el=>el.classList.contains('sheet-close'))||focusableElements(panel)[0]||panel).focus()},
  keepFocus(event){const scope=this.$el.closest('.phone-frame')||this.$el.parentElement;if(this.contained&&scope&&!scope.contains(event.target))return;if(this.modalSession&&isTopModal(this.modalSession)&&this.$refs.panel&&!this.$refs.panel.contains(event.target))this.focusInitial()},
  onKey(event){const scope=this.$el.closest('.phone-frame')||this.$el.parentElement;if(this.contained&&scope&&!scope.contains(document.activeElement))return;if(!this.modalSession||!isTopModal(this.modalSession))return;if(event.key==='Escape'){event.preventDefault();event.stopImmediatePropagation();this.requestClose('escape');return}if(event.key!=='Tab')return;const controls=focusableElements(this.$refs.panel);if(!controls.length){event.preventDefault();this.$refs.panel.focus();return}const first=controls[0],last=controls[controls.length-1],active=document.activeElement;if(event.shiftKey&&(active===first||!this.$refs.panel.contains(active))){event.preventDefault();last.focus()}else if(!event.shiftKey&&(active===last||active===this.$refs.panel)){event.preventDefault();first.focus()}},
  requestClose(reason){if(!this.modalSession||!isTopModal(this.modalSession))return;if(this.busy||!this.dismissible){this.$emit('dismiss-blocked',reason);return}this.$emit('input',false);this.$emit('close',reason)},
  toggleDetent(){if(this.suppressHandleClick){this.suppressHandleClick=false;return}if(!this.busy)this.activeDetent=this.activeDetent==='large'?'medium':'large'},resizeKey(event){if(this.busy)return;if(event.key==='ArrowUp'||event.key==='ArrowDown'){event.preventDefault();this.activeDetent=event.key==='ArrowUp'?'large':'medium'}},
  dragStart(event){if(this.busy||event.button!==0)return;this.dragOrigin={y:event.clientY,id:event.pointerId};event.currentTarget.setPointerCapture(event.pointerId)},dragMove(event){if(this.dragOrigin&&event.pointerId===this.dragOrigin.id)this.dragY=Math.max(-30,event.clientY-this.dragOrigin.y)},dragEnd(event){if(!this.dragOrigin)return;const delta=event.clientY-this.dragOrigin.y;this.suppressHandleClick=Math.abs(delta)>6;this.dragCancel();if(this.busy)return;if(delta<-45)this.activeDetent='large';else if(delta>80){if(this.activeDetent==='large')this.activeDetent='medium';else this.requestClose('swipe')}},dragCancel(){this.dragOrigin=null;this.dragY=0}
}}
</script>
